import{_ as o}from"./chunks/workspace-overview.CaliAD9t.js";import{_ as r,o as e,c as a,a2 as i}from"./chunks/framework.mRCPFc5l.js";const S=JSON.parse('{"title":"开始使用","description":"","frontmatter":{},"headers":[],"relativePath":"01-getting-started.md","filePath":"zh-CN/01-getting-started.md"}'),l={name:"01-getting-started.md"};function d(n,t,s,c,p,g){return e(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="开始使用" tabindex="-1">开始使用 <a class="header-anchor" href="#开始使用" aria-label="Permalink to &quot;开始使用&quot;">​</a></h1><p>了解 GridSubStudio 的基本工作方式，并完成第一个字幕项目。</p><h2 id="你可以在本页完成什么" tabindex="-1">你可以在本页完成什么 <a class="header-anchor" href="#你可以在本页完成什么" aria-label="Permalink to &quot;你可以在本页完成什么&quot;">​</a></h2><ul><li>新建或打开一个项目。</li><li>判断应该使用项目模式还是旧版 CSV 模式。</li><li>认识表格、视频、时间轴和常用工具入口。</li><li>按推荐顺序完成一次字幕审校。</li></ul><h2 id="安装并启动-gridsubstudio" tabindex="-1">安装并启动 GridSubStudio <a class="header-anchor" href="#安装并启动-gridsubstudio" aria-label="Permalink to &quot;安装并启动 GridSubStudio&quot;">​</a></h2><p>GridSubStudio 提供 Windows x64 安装包和 macOS Apple Silicon 测试版。两平台使用相同的项目和字幕编辑流程；请选择对应系统的安装包。当前 Mac 测试版要求 <strong>macOS 27.0 或更高版本</strong>，暂不提供 Intel Mac 安装包。普通用户无需安装 Python、Node.js 或 Rust。</p><h3 id="windows-安装" tabindex="-1">Windows 安装 <a class="header-anchor" href="#windows-安装" aria-label="Permalink to &quot;Windows 安装&quot;">​</a></h3><p>运行发布方提供的 <code>.msi</code>，按提示完成安装，从开始菜单或桌面快捷方式启动 GridSubStudio。</p><h3 id="macos-安装" tabindex="-1">macOS 安装 <a class="header-anchor" href="#macos-安装" aria-label="Permalink to &quot;macOS 安装&quot;">​</a></h3><ol><li>下载 Apple Silicon 版 <code>.dmg</code> 并双击打开。</li><li>将 <strong>GridSubStudio.app</strong> 拖到 <strong>Applications（应用程序）</strong>。</li><li>弹出磁盘映像，再从“应用程序”启动 GridSubStudio。后续更新需要应用所在目录可写。</li></ol><h3 id="macos-首次启动-绕过-gatekeeper-拦截" tabindex="-1">macOS 首次启动：绕过 Gatekeeper 拦截 <a class="header-anchor" href="#macos-首次启动-绕过-gatekeeper-拦截" aria-label="Permalink to &quot;macOS 首次启动：绕过 Gatekeeper 拦截&quot;">​</a></h3><p>当前 Mac 测试版未经 Apple Developer ID 签名和公证，首次打开可能提示无法验证开发者或 Apple 无法检查恶意软件。确认安装包来自可信发布方、未被修改后，可按以下步骤为 GridSubStudio 单独放行：</p><ol><li>先尝试打开“应用程序”里的 <strong>GridSubStudio</strong>，关闭拦截提示。</li><li>打开 <strong>系统设置 → 隐私与安全性</strong>，找到 GridSubStudio 被阻止的提示，点击 <strong>仍要打开</strong>。</li><li>按系统提示完成身份验证，在再次出现的确认窗口中点击 <strong>打开</strong>。</li></ol><p>系统会记住这个应用的例外，之后可以正常启动。若找不到按钮，重新尝试打开应用后再检查；受单位管理的 Mac 可能需要管理员处理。若提示文件损坏，先重新下载并核对发布方提供的校验值；若提示将损坏电脑，不应当作普通的未公证提示处理。</p><p>这是针对单个应用的例外，不需要关闭系统的 Gatekeeper。操作依据：<a href="https://support.apple.com/zh-cn/102445" target="_blank" rel="noreferrer">Apple 官方说明</a>。</p><p>应用启动后，顶部会显示 <strong>新建项目</strong>、<strong>打开项目</strong>、<strong>项目设置</strong>、<strong>机器翻译</strong>、<strong>导出</strong>、<strong>旧版</strong>、<strong>撤销</strong>、<strong>重做</strong>和 <strong>设置</strong> 等入口。没有打开工作区时，表格区域会提示打开或新建项目。</p><blockquote><p>如果应用提示存在新版本，可以选择立即安装或稍后处理。更新安装完成后应用会重新启动。</p></blockquote><h2 id="新建字幕项目" tabindex="-1">新建字幕项目 <a class="header-anchor" href="#新建字幕项目" aria-label="Permalink to &quot;新建字幕项目&quot;">​</a></h2><ol><li>点击顶部的 <strong>新建项目</strong>。</li><li>在系统窗口中选择或创建一个空的项目文件夹。</li><li>项目设置窗口打开后，导入原文字幕、译文字幕和视频。</li><li>检查每个文件对应的集数。</li><li>设置质量阈值、目标语言和拼写词典。</li><li>点击 <strong>确认</strong> 创建工作区。</li></ol><p>创建后，项目文件夹将保存项目配置、字幕工作区、草稿和相关资源引用。以后应使用 <strong>打开项目</strong> 重新进入，而不是直接打开其中的 <code>workspace.csv</code>。</p><p>详细导入步骤见<a href="./02-importing-resources.html">导入素材</a>。</p><h2 id="打开已有项目" tabindex="-1">打开已有项目 <a class="header-anchor" href="#打开已有项目" aria-label="Permalink to &quot;打开已有项目&quot;">​</a></h2><ol><li>点击 <strong>打开项目</strong>。</li><li>选择包含 <code>project.json</code> 的项目文件夹。</li><li>等待工作区、草稿和资源状态加载完成。</li></ol><p>应用会尽量恢复上次使用的字幕行、视频、播放位置、列宽、筛选、排序、时间轴缩放和拼写检查状态。</p><p>如果提示项目已在另一窗口打开，请先回到那个窗口继续工作，或正常关闭它后再试。异常退出产生的过期锁通常会在重新打开时自动恢复，不要手动删除项目文件。</p><h2 id="打开和迁移旧版-csv" tabindex="-1">打开和迁移旧版 CSV <a class="header-anchor" href="#打开和迁移旧版-csv" aria-label="Permalink to &quot;打开和迁移旧版 CSV&quot;">​</a></h2><p>顶部 <strong>旧版</strong> 菜单保留了直接编辑单个 CSV 的工作方式：</p><ul><li><strong>打开旧版 CSV</strong>：直接打开、编辑和保存一个 CSV。</li><li><strong>将旧版转换为项目</strong>：把当前旧版工作区迁移到新的项目文件夹。</li><li><strong>视频文件夹</strong>：为旧版 CSV 选择视频文件夹。</li><li><strong>导出 XLSX</strong>：把当前表格导出为 Excel 工作簿。</li></ul><p>新工作建议使用项目模式。旧版模式适合临时编辑现有 CSV，或迁移旧工作区；机器翻译和项目字幕导出仅在项目模式中提供。</p><h2 id="认识主工作区" tabindex="-1">认识主工作区 <a class="header-anchor" href="#认识主工作区" aria-label="Permalink to &quot;认识主工作区&quot;">​</a></h2><p><img src="'+o+'" alt="GridSubStudio 中文主工作区，左侧为字幕表格，右侧为视频和时间轴"></p><p>主工作区由四个部分组成：</p><ol><li><strong>顶部工具栏</strong>：项目、保存、导出、撤销、设置等全局操作。</li><li><strong>字幕表格</strong>：查看、选择、编辑、查找和批量处理字幕行。</li><li><strong>视频区域</strong>：选择视频、播放、暂停、切换字幕或分集、调整速度。</li><li><strong>时间轴</strong>：查看字幕块、播放头和时间范围，点击或拖动完成定位与时间调整。</li></ol><p>表格和视频区域之间的分隔条可以拖动。窗口较窄时两侧仍保持并排，必要时可缩小界面大小或拖动分隔条。</p><h2 id="完成一次基本审校流程" tabindex="-1">完成一次基本审校流程 <a class="header-anchor" href="#完成一次基本审校流程" aria-label="Permalink to &quot;完成一次基本审校流程&quot;">​</a></h2><p>推荐按以下顺序工作：</p><ol><li>在 <strong>项目设置</strong> 中导入素材并确认集数。</li><li>在表格中选择一行，通过视频和时间轴核对上下文。</li><li>编辑 <code>translation</code> 等需要修改的字段。</li><li>使用查找、筛选、行操作和批量替换处理重复问题。</li><li>使用质量摘要和拼写检查定位遗漏。</li><li>根据需要运行机器翻译并审查结果。</li><li>保存项目，查看未保存差异。</li><li>通过导出向导生成 SRT 或 ASS。</li></ol><h2 id="查看快捷键和操作帮助" tabindex="-1">查看快捷键和操作帮助 <a class="header-anchor" href="#查看快捷键和操作帮助" aria-label="Permalink to &quot;查看快捷键和操作帮助&quot;">​</a></h2><p>在 <strong>设置 → 快捷键</strong> 中可以查看完整列表。常用快捷键包括：</p><p>下表使用 <code>Ctrl</code> 表示 Windows 修饰键；macOS 使用 <code>Command（⌘）</code>。Mac 多范围选择、复制/剪切/粘贴同样使用 Command。功能键 F7 可能需要配合 Fn，取决于系统键盘设置。</p><p>例外：macOS 的 <code>Command+H</code> 是系统隐藏窗口快捷键，高级查找/替换请点击界面按钮或使用 <code>Ctrl+H</code>。参见 <a href="https://support.apple.com/zh-cn/102650" target="_blank" rel="noreferrer">Apple 快捷键说明</a>。</p><table tabindex="0"><thead><tr><th>操作</th><th>快捷键</th></tr></thead><tbody><tr><td>保存</td><td><code>Ctrl+S</code></td></tr><tr><td>撤销</td><td><code>Ctrl+Z</code></td></tr><tr><td>重做</td><td><code>Ctrl+Y</code> 或 <code>Ctrl+Shift+Z</code></td></tr><tr><td>查找</td><td><code>Ctrl+F</code></td></tr><tr><td>高级查找/替换</td><td><code>Ctrl+H</code></td></tr><tr><td>拼写检查</td><td><code>F7</code></td></tr><tr><td>播放/暂停</td><td><code>Space</code></td></tr><tr><td>上一条/下一条字幕</td><td><code>Arrow Up</code> / <code>Arrow Down</code></td></tr><tr><td>清空选中单元格</td><td><code>Delete</code></td></tr><tr><td>关闭当前面板</td><td><code>Esc</code></td></tr></tbody></table><p>打开对话框时，后台的播放和全局编辑快捷键会暂停响应，防止误操作。</p><h2 id="遇到问题" tabindex="-1">遇到问题 <a class="header-anchor" href="#遇到问题" aria-label="Permalink to &quot;遇到问题&quot;">​</a></h2><ul><li><strong>项目打不开</strong>：确认选择的是项目文件夹，并检查是否在其他窗口中打开。</li><li><strong>只有 CSV，没有项目文件夹</strong>：先用 <strong>打开旧版 CSV</strong>，再选择 <strong>将旧版转换为项目</strong>。</li><li><strong>界面显示不全</strong>：在 <strong>设置 → 界面大小</strong> 中调低比例，或拖动表格与视频之间的分隔条。</li><li><strong>按钮不可用</strong>：通常表示尚未打开项目、没有选中字幕，或当前操作需要先完成导入。</li></ul>',45)])])}const m=r(l,[["render",d]]);export{S as __pageData,m as default};
